\label{lemma:pe}\vspace{0.1cm}
Let the persistence of excitation condition \eqref{eq:pe} hold and assume that there exists $C>0$ such that $\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\originalleft\lVert W(t)\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\originalright\rVert<C$ for each $t \in \mathbb{R}$. Then there exists $M>0$ and $\zeta>0$ such that for each $t_1, t_2 \in \mathbb{R}$
\begin{equation}
    \|\Phi(t_1,t_2)\| \leq Me^{-\zeta(t_1 -t_2)} 
\end{equation}
with $\Phi(t_1,t_2)$ defined as above. \vspace{0.1cm}

\vspace{0.1cm}\label{lemma:grad_estimate}
Let Assumptions \ref{ass:bounded_reference}-\ref{ass:bounded_trajectories} hold. Then $\Delta \hat{J}_k(\cdot | \theta_k, x_k, e_k)$ is a sub-Gaussian distribution where
\begin{equation}\label{eq:grad_error}
    \mathbb{E}[\Delta \hat{J}_k(\cdot | \theta_k, x_k, e_k)] = W_k^TW_k\phi_{k} + O(\Delta t(1 + \sigma + \sigma^2))
\end{equation}
and 
\begin{equation}
    \mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\originalleft\lVert \Delta \hat{J}_k(\cdot | \theta_k, x_k, e_k)\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\originalright\rVert_{\psi_2}= O\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left(\frac{1}{\sigma}\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right).
\end{equation}\vspace{0.1cm}

\label{lemma:noise_characterization}
Let Assumptions \ref{ass:bounded_reference}-\ref{ass:bounded_trajectories} hold. Then $ \Delta_{k}^e(\cdot|\theta_k, x_k, e_k)$ and $ \Delta_{k}^\phi(\cdot|\theta_k, x_k, e_k)$ are sub-Gaussian random variables where
\begin{equation}\label{lemma:total_disturbance}
   \| E[ \Delta_{k}^e(\cdot|\theta_k, x_k, e_k) ]\|_2 =O(\Delta t^2(1 + \sigma+ \sigma^2) ) \vspace{-1.5em}
\end{equation}
\begin{equation}
\| E[ \Delta_{k}^\phi(\cdot|\theta_k, x_k, e_k) ]\|_2 =O(\Delta t^2(1 + \sigma+ \sigma^2)) \vspace{-1em}
\end{equation}
\begin{equation}
    \|\Delta_k^e(\cdot |\theta_k, x_k,e_k)\|_{\psi_2} = O(\Delta t \sigma) \vspace{-1em}
\end{equation}
\begin{equation}
    \|\Delta_k^\phi(\cdot |\theta_k, x_k,e_k)\|_{\psi_2} = O\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left(\frac{\Delta t }{\sigma}\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right).
\end{equation}
\vspace{0.5em}

\label{thm:convergence}\vspace{0.1cm}
Let Assumptions \ref{ass:bounded_reference}-\ref{ass:bounded_trajectories} hold. Further assume that $W^T W$ is persistently exciting and let $M>0$ and $\zeta>0$ be defined as in Lemma \ref{lemma:pe}. Then there exists numerical constants $C_1>0$ and $C_2>0$ such that 
\begin{equation}\label{eq:total_bias}
   |\mathbb{E}[X_k]| \leq M\rho^k | X_0| + M C_1\frac{\Delta t(1 + \sigma + \sigma^2)}{\zeta}
\end{equation}
and for each $\lambda>0$ with probability $1-\lambda$ we have
\begin{equation}\label{eq:total_var}
    |X_k - \mathbb{E}[X_k]| \leq C_2 M\sqrt{\frac{ \Delta t \ln\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left( \frac{2}{\lambda}\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right)}{\zeta \sigma^2}}
\end{equation}\vspace{0.1cm}

\label{lemma:tot_bound}
\ref{ass:bounded_reference}-\ref{ass:bounded_trajectories} hold. Then there exists a constant $C>0$ such that 
\begin{multline}\label{eq:boundy_1}
\sup_{t\in [t_k, t_{k})}\sup \bigg\{ \mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\originalleft\lVert A_p(x(t))\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\originalright\rVert, \mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\originalleft\lVert B_p(x(t))\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\originalright\rVert, \mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\originalleft\lVert f_p(x(t))\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\originalright\rVert, \mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\originalleft\lVert g_p(x(t))\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\originalright\rVert, \mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\originalleft\lVert \frac{d}{dx}A_p(x(t))\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\originalright\rVert, \mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\originalleft\lVert \frac{d}{dx}B_p(x(t))\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\originalright\rVert, \\ \mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\originalleft\lVert \frac{d}{dx}f_p(x(t))\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\originalright\rVert, \mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\originalleft\lVert \frac{d}{dx}g_p(x(t))\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\originalright\rVert \bigg \}< C 
